+    protected readonly startedAt = Date.now();
+    protected quitting = false;
+
+    protected quitStale(why: string): void {
+        if (this.quitting) {
+            return;
+        }
+        this.quitting = true;
+        log.error(`${why}: quitting, so the next launch starts a whole, current app`);
+        app.quit();
+        setTimeout(() => app.exit(1), 5000).unref();
+    }
