             }
             if (backendPid === undefined) {
-                try {
-                    backendPid = JSON.parse(fs.readFileSync(registry, 'utf8')).pid;
-                } catch {
-                    /* not registered yet */
-                }
+                backendPid = this.registeredBackend()?.pid;
                 return;
             }
-            try {
-                process.kill(backendPid, 0);
-            } catch (e) {
-                if ((e as NodeJS.ErrnoException).code === 'ESRCH') {
